package main

import "html/template"

const style = `<style>
:root{color-scheme:dark;--bg:#0b111c;--panel:#141e2e;--line:#293951;--text:#eaf0f9;--muted:#a5b5ca;--accent:#8ab9ff;--good:#81e0af}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#172a43 0,transparent 45%),var(--bg);color:var(--text);font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}main{max-width:1100px;margin:auto;padding:48px 24px 80px}h1,h2,h3,p{margin-top:0}h1{font-size:30px;letter-spacing:-.04em;margin-bottom:3px}h2{font-size:19px;margin:0}.eyebrow{text-transform:uppercase;letter-spacing:.13em;color:var(--accent);font-size:11px;font-weight:700;margin-bottom:8px}.muted,small{color:var(--muted)}.header,.card-head,.actions{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.actions{justify-content:flex-start;gap:8px}.status-line{margin:26px 0 12px;color:var(--muted);font-size:13px}.card,.notice{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:22px;margin:14px 0}.notice{color:#c8d8ed;background:#14243a}.error{color:#ffadad}.success,.active{color:var(--good)}.offline{color:var(--muted)}.tag{font-size:12px;border:1px solid #3a4d66;border-radius:100px;padding:3px 10px;color:#b8c9de}.divider{border:0;border-top:1px solid var(--line);margin:18px 0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:730px}td,th{text-align:left;padding:14px 9px;border-bottom:1px solid var(--line);vertical-align:top}th{font-weight:500;color:var(--muted);font-size:12px}td{font-size:14px}input,textarea,button,.button{font:inherit;border-radius:8px}input,textarea{background:#0c1523;color:var(--text);border:1px solid #425674;padding:9px 11px;max-width:100%}input:focus,textarea:focus,button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:2px}button,.button{display:inline-block;border:1px solid #90bfff;background:#a9cbff;color:#102035;padding:8px 12px;text-decoration:none;cursor:pointer;font-weight:600}button.secondary,.button.secondary{background:#1c2d43;color:#dce9fa;border-color:#41546d}button.danger{background:transparent;border-color:#a95a65;color:#ffb7bf}button:hover,.button:hover{filter:brightness(1.1)}a{color:#a9cbff}form.inline{display:inline}label{display:block;margin:12px 0 5px;color:#cbd8e9}label input:not([type=checkbox]){display:block;width:min(100%,480px);margin-top:5px}label.check input{margin-right:6px}details{margin:14px 0}summary{cursor:pointer;color:#b8d5ff;font-weight:600}details form{margin-top:12px}.form-note{max-width:760px;line-height:1.6}.action-forms form{margin:12px 0}.link{width:100%;font-family:monospace}.qr{background:white;padding:12px;width:280px;max-width:100%;border-radius:10px}.login{max-width:430px;margin:12vh auto 0}.footer{font-size:12px;color:var(--muted);margin-top:28px}.empty{padding:22px 4px;color:var(--muted)}@media(max-width:600px){main{padding:30px 16px 60px}.card{padding:17px}.header{align-items:flex-start}.header .actions{width:100%}h1{font-size:27px}}
</style>`

var loginHTML = template.Must(template.New("login").Parse(`<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登录 · Mini XUI</title>` + style + `</head><body><main><div class="login">
<div class="eyebrow">Xray 管理面板</div><h1>Mini XUI</h1><p class="muted">登录以管理节点、用户和流量。</p>
<section class="card">{{if .Failed}}<p class="error" role="alert">密码不正确，请重试。</p>{{end}}<form method="post"><label>管理密码<input type="password" name="password" required autofocus autocomplete="current-password"></label><button>登录面板</button></form></section>
<p class="footer">面板仅监听本机，请通过 SSH 隧道访问。</p></div></main></body></html>`))

var indexHTML = template.Must(template.New("index").Parse(`<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>控制台 · Mini XUI</title>` + style + `</head><body><main>
<header class="header"><div><div class="eyebrow">Xray 管理面板</div><h1>Mini XUI</h1><div class="muted">管理节点、用户和流量</div></div><div class="actions">
<a class="button secondary" href="/">刷新状态</a>{{if .CanRestart}}
<form class="inline" method="post" action="/restart" onsubmit="return confirm('重启会短暂中断此实例的代理连接，确定应用已保存的配置？')"><input type="hidden" name="token" value="{{.Token}}"><button>重启并应用配置</button></form>{{end}}</div></header>
<p class="status-line">{{.Updated}} · 活跃状态以 Xray 数据为准 · 速率为采集周期内的平均值</p>
{{if .Error}}<div class="notice error">{{.Error}}</div>{{end}}{{if .Notice}}<div class="notice success">{{.Notice}}</div>{{end}}
<div class="notice">配置和用户变更保存后，{{if .CanRestart}}点击“重启并应用配置”{{else}}手动重启 Xray{{end}}才能生效。分享链接使用已保存的配置。</div>
{{range .Inbounds}}<section class="card"><div class="card-head"><div><div class="eyebrow">入站协议</div><h2>{{if eq .Protocol "vless"}}VLESS · Reality{{else}}Hysteria 2 · TLS{{end}}</h2></div><span class="tag">端口 {{.Port}} · {{len .Clients}} 位用户</span></div>
<details><summary>协议配置</summary><form method="post" action="/change"><input type="hidden" name="token" value="{{$.Token}}"><input type="hidden" name="action" value="settings"><input type="hidden" name="inbound" value="{{.Index}}">
<label>监听端口<input type="number" name="port" min="1" max="65535" value="{{.Port}}" required></label>
{{if eq .Protocol "vless"}}<label>Reality 目标地址<input name="target" value="{{.Target}}" required placeholder="example.com:443"></label><label>服务名称，多个用逗号分隔<input name="serverNames" value="{{.ServerNames}}" required></label><label>Short ID，多个用逗号分隔<input name="shortIds" value="{{.ShortIDs}}"></label><label>Reality 私钥<input type="password" name="privateKey" autocomplete="new-password" placeholder="留空则不修改"></label>
{{else}}<label>TLS 服务名称<input name="tlsServerName" value="{{.TLSServerName}}"></label><label>证书路径<input name="certFile" value="{{.CertFile}}" required></label><label>私钥路径<input name="keyFile" value="{{.KeyFile}}" required></label><label>ALPN，多个用逗号分隔<input name="alpn" value="{{.ALPN}}" placeholder="h3"></label>{{end}}
<button>校验并保存</button><p class="muted form-note">保存前会使用 Xray 校验并备份配置。更改端口前请检查其他服务及防火墙；连接参数变化后，客户端可能需要重新导入。</p></form></details><hr class="divider">
<div class="table-wrap"><table><thead><tr><th>用户标识</th><th>状态</th><th>累计上行</th><th>累计下行</th><th>平均速率（上 / 下）</th><th>操作</th></tr></thead><tbody>{{$i:=.Index}}{{$proto:=.Protocol}}{{range .Clients}}
<tr><td>{{.Email}}</td><td class="{{if eq .Online "活跃"}}active{{else}}offline{{end}}">{{.Online}}</td><td>{{.Up}}</td><td>{{.Down}}</td><td>{{.RateUp}} / {{.RateDown}}</td><td>
<a class="button secondary" href="/share?inbound={{$i}}&amp;client={{.Index}}">二维码 / 链接</a><details><summary>编辑或删除</summary><div class="action-forms">
<form method="post" action="/change"><input type="hidden" name="token" value="{{$.Token}}"><input type="hidden" name="action" value="edit"><input type="hidden" name="inbound" value="{{$i}}"><input type="hidden" name="client" value="{{.Index}}"><label>用户凭据<input name="credential" value="{{.Credential}}" required></label>{{if eq $proto "vless"}}<label class="check"><input type="checkbox" name="vision" {{if eq .Flow "xtls-rprx-vision"}}checked{{end}}>Vision 流控</label>{{end}}<button>保存用户</button></form>
<form method="post" action="/change" onsubmit="return confirm('确定删除此用户？')"><input type="hidden" name="token" value="{{$.Token}}"><input type="hidden" name="action" value="delete"><input type="hidden" name="inbound" value="{{$i}}"><input type="hidden" name="client" value="{{.Index}}"><button class="danger">删除用户</button></form></div></details></td></tr>{{else}}<tr><td colspan="6" class="muted">暂无用户，可在下方添加。</td></tr>{{end}}</tbody></table></div>
<details><summary>添加用户</summary><form method="post" action="/change"><input type="hidden" name="token" value="{{$.Token}}"><input type="hidden" name="action" value="add"><input type="hidden" name="inbound" value="{{.Index}}"><label>用户标识<input name="email" required maxlength="128" placeholder="例如 phone"></label><label>用户凭据<input name="credential" placeholder="留空自动生成"></label>{{if eq .Protocol "vless"}}<label class="check"><input type="checkbox" name="vision">Vision 流控</label>{{end}}<button>添加并保存</button></form><small>用户标识用于流量统计，在所有入站中必须唯一。</small></details></section>
{{else}}<div class="card empty">未找到支持的入站。请检查 Xray 配置是否包含 VLESS 或 Hysteria 入站。</div>{{end}}
<footer class="footer">流量为本面板采集的累计值，在线状态由 Xray 提供。</footer></main></body></html>`))

var shareHTML = template.Must(template.New("share").Parse(`<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>节点分享 · Mini XUI</title>` + style + `</head><body><main><a href="/">← 返回控制台</a><section class="card"><div class="eyebrow">节点分享</div><h1>扫描二维码</h1><p class="muted form-note">使用支持该协议的客户端扫描。二维码和链接包含用户凭据，请妥善保管。</p><img class="qr" alt="节点分享二维码" src="data:image/png;base64,{{.Image}}"><label for="link">分享链接</label><textarea class="link" rows="5" readonly id="link">{{.Link}}</textarea><p><button type="button" onclick="if(navigator.clipboard){navigator.clipboard.writeText(document.getElementById('link').value).then(()=>this.textContent='已复制')}else{document.getElementById('link').select()}">复制链接</button></p><small>分享链接使用已保存的配置；修改后请先应用配置再连接。</small></section></main></body></html>`))
